import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 28 大过：超常承担与结构极限至30 离：光明有所依附，也有盛衰","description":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","frontmatter":{"title":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 28 大过：超常承担与结构极限至30 离：光明有所依附，也有盛衰","description":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","splitFrom":"life/personal/yijing/hexagrams-25-32.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读四：无妄大畜颐大过至坎离咸恒","summary":"对读《周易》与《周易正义》，逐爻理解第二十五至第三十二卦的无妄、积养、重险、光明、感应与恒久。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 25 无妄：真实行事，也承认意外至27 颐：谁在养我，我又养什么","link":"/life/personal/yijing/hexagrams-25-32-part-01"},"next":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 31 咸：感应不是操控至读后比较与自测","link":"/life/personal/yijing/hexagrams-25-32-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 25 无妄：真实行事，也承认意外至27 颐：谁在养我，我又养什么","link":"/life/personal/yijing/hexagrams-25-32-part-01"},"next":{"text":"六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 31 咸：感应不是操控至读后比较与自测","link":"/life/personal/yijing/hexagrams-25-32-part-03"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-25-32-part-02.md","filePath":"life/personal/yijing/hexagrams-25-32-part-02.md"}'),o={name:"life/personal/yijing/hexagrams-25-32-part-02.md"};function s(i,t,d,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读四-无妄大畜颐大过至坎离咸恒-·-28-大过-超常承担与结构极限至30-离-光明有所依附-也有盛衰" tabindex="-1">六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 28 大过：超常承担与结构极限至30 离：光明有所依附，也有盛衰 <a class="header-anchor" href="#六十四卦详读四-无妄大畜颐大过至坎离咸恒-·-28-大过-超常承担与结构极限至30-离-光明有所依附-也有盛衰" aria-label="Permalink to &quot;六十四卦详读四：无妄大畜颐大过至坎离咸恒 · 28 大过：超常承担与结构极限至30 离：光明有所依附，也有盛衰&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-25-32">返回分篇目录</a></p><p>本组先读无妄与大畜，再看颐的养、大过的承载极限，随后以坎离结束上经、以咸恒开启下经。上下经的划分不等于“上经只有天道、下经只有人事”：孔颖达在咸卦疏中已经讨论并反对这种过度割裂，因为每个六爻卦都兼涉天地人。</p><p>本文逐卦实际查阅《周易》经传与《周易正义》卷三、卷四对应篇。原文保留古字、繁体，简体解释为本篇概括；疑难处并列读法，不将古注当成唯一译文。大畜“曰閑輿衛”、坎“樽酒簋貳”、离“大耋之嗟”、恒“振恒”等参照《正义》录文，其他页面可能有异体或异文。古籍中的吉凶、疾病与灾害语句不构成现代预测或诊疗依据。</p><h2 id="gua-28" tabindex="-1">28 大过：超常承担与结构极限 <a class="header-anchor" href="#gua-28" aria-label="Permalink to &quot;28 大过：超常承担与结构极限 {#gua-28}&quot;">​</a></h2><p><strong>卦符：䷛　上卦：兑 ☱（泽）　下卦：巽 ☴（木、风）。</strong></p><p><strong>卦辞原文</strong>：大過：棟橈，利有攸往，亨。</p><p><strong>白话概括</strong>：四阳居中、两端阴柔，古传取栋梁受压弯曲之象。大过的过是超过、过越，不只指犯错。《正义》联系衰难之世以非常行动救难，但栋橈始终提醒：勇于承担不能取消结构强度，离开支持条件的英雄姿态也可能失败。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：藉用白茅，无咎。</td><td>用洁白茅草垫在物下，慎重保护，即使谨慎有余也无咎。藉是衬垫，不是借用。</td></tr><tr><td>九二：枯楊生稊，老夫得其女妻，无不利。</td><td>枯杨根部或嫩芽重新萌生，以老夫少妻比喻获得新生支持。婚龄与性别比喻属古代社会，不是现代婚配处方。</td></tr><tr><td>九三：棟橈，凶。</td><td>栋梁弯曲，不能承受压力。刚强若缺少合宜支援，并不自动有利。</td></tr><tr><td>九四：棟隆，吉。有它吝。</td><td>栋梁能够撑起，吉；若另有所牵累，又会困窘。稳定支撑与分散承诺之间需要辨别。</td></tr><tr><td>九五：枯楊生華，老婦得其士夫，无咎无譽。</td><td>枯杨开花，与九二生稊不同，古注认为难持久。没有咎责也没有赞誉，不宜把表面繁盛当成深层更新。</td></tr><tr><td>上六：過涉滅頂，凶，无咎。</td><td>涉水过深以至灭顶，结果凶而又称无咎。古注区分救难之志与失败后果，不能由无咎抹去生命危险。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“澤滅木，大過；君子以獨立不懼，遯世无悶。”</p><p><strong>解释</strong>：泽水淹木，环境已超常。君子可独立而不惧，也可退隐而不怨；坚持与退出都是可能的选择，不是只有奋不顾身一种姿态。</p><p><strong>整体读法与误区</strong>：九二生稊、九五生华，适合比较根本恢复与短时表象；九三栋橈、九四栋隆，适合比较支撑失效与有效。上六尤其说明“凶”与“咎”并非同义：结果坏未必全是道德过失，动机可敬也不能使危险消失。不要把大过读成鼓励透支身体和资源的赞歌。</p><p><strong>细读线索</strong>：大过的四阳连在中间，初、上两端为阴，故彖传说本末弱。问题并不是力量总量太少，而可能是力量集中、支点不足；这是栋梁意象能给出的结构理解。九三与九四相邻却分别橈与隆，不能因为都是阳爻便给相同判断。上六又越过可承受水深，把结构问题转成行动后果。由此可分清拥有力量、安排支撑、选择步幅三个层次，它们不能互相替代。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%A7%E9%81%8E" target="_blank" rel="noopener noreferrer">《周易·大过》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E5%A4%A7%E9%81%8E" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·大过》</a>。</p><h2 id="gua-29" tabindex="-1">29 坎：重险中的学习与可行小步 <a class="header-anchor" href="#gua-29" aria-label="Permalink to &quot;29 坎：重险中的学习与可行小步 {#gua-29}&quot;">​</a></h2><p><strong>卦符：䷜　上卦：坎 ☵（水、险）　下卦：坎 ☵（水、险）。</strong></p><p><strong>卦辞原文</strong>：習坎：有孚，維心亨，行有尚。</p><p><strong>白话概括</strong>：两个坎相重，险中仍有险。《正义》把习解释为重叠与学习熟习两层：困难不能只凭勇气闯，要熟悉其事。维心亨也不是说外在障碍全靠心态化解，而是在局势未通时仍保持内在可信与中正，再寻找确有根据的行动。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：習坎，入于坎窞，凶。</td><td>本已处险，又陷入更深坑穴。窞是坑中之陷，提醒不要因慌乱继续加深危险。</td></tr><tr><td>九二：坎有險，求小得。</td><td>危险尚未解除，只能争取有限成果。承认可得范围，不把局部改善误报为全部出险。</td></tr><tr><td>六三：來之坎坎，險且枕，入于坎窞，勿用。</td><td>往来都遇险，处境不稳，不宜强行施用。枕有倚止等异解，不能仅按睡枕理解。</td></tr><tr><td>六四：樽酒簋貳，用缶，納約自牖，終无咎。</td><td>一樽酒、二簋食，器具简朴，经窗纳入；古注重明信而不假外饰。“纳约自牖”亦有不同申说。</td></tr><tr><td>九五：坎不盈，祗既平，无咎。</td><td>险坑尚待平复，不求过满而得无咎。祗、禔等有异文，其训释与水平之象应联系全爻理解。</td></tr><tr><td>上六：係用徽纆，寘于叢棘，三歲不得，凶。</td><td>被绳索拘系，置于丛棘之中，长期不能脱出，呈现严重困局。徽纆是绳索，三岁不是具体解困预约。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“水洊至，習坎；君子以常德行，習教事。”</p><p><strong>解释</strong>：水接连而至，君子让德行保持常度，并反复熟习教事。洊是再至、接续。可持续的练习与制度准备，比临时自我激励更贴合这里的习字。</p><p><strong>整体读法与误区</strong>：坎不是遇到困难就算凶命，九二有小得，六四可无咎，但初、三、上也写出无效行动与深陷。读时应同时看见可做与不可做。现代可借它提醒风险识别、演练和阶段性目标；面对真实危险仍需具体安全措施，不能以“心亨”要求人在伤害中仅靠忍耐。</p><p><strong>细读线索</strong>：两个坎各以一阳居中、两阴在外，王、孔以此解释内刚而外险。九二和九五都在中位，仍分别写求小得与坎不盈，说明居中不自动意味着已经脱险。六四反而以简薄器物与明信相接求无咎，给重险中的关系留下可通之处。读者可以把外在局势、内在持守、人与人之间的沟通分别列出，再检视每一爻究竟处理了其中哪一层，而不要将它们混成心态好坏。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%9D%8E" target="_blank" rel="noopener noreferrer">《周易·坎》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E5%9D%8E" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·坎》</a>。</p><h2 id="gua-30" tabindex="-1">30 离：光明有所依附，也有盛衰 <a class="header-anchor" href="#gua-30" aria-label="Permalink to &quot;30 离：光明有所依附，也有盛衰 {#gua-30}&quot;">​</a></h2><p><strong>卦符：䷝　上卦：离 ☲（火、明）　下卦：离 ☲（火、明）。</strong></p><p><strong>卦辞原文</strong>：離：利貞，亨。畜牝牛，吉。</p><p><strong>白话概括</strong>：离在这里主要从丽、附着解释，不是现代“离开”的意思。《彖》以日月丽天、草木丽土说明万物有所依；《正义》指出依附要正，方能亨通。牝牛取柔顺而有用之象，不是规定读者养一头母牛，也不是说光明可以完全脱离承载它的条件。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：履錯然，敬之无咎。</td><td>行步交错、事务繁杂，须敬慎以免过失。清楚秩序往往从初始动作开始。</td></tr><tr><td>六二：黃離，元吉。</td><td>黄取中，明而居中，是适度光明之象。不是颜色本身具备保证好运的力量。</td></tr><tr><td>九三：日昃之離，不鼓缶而歌，則大耋之嗟，凶。</td><td>日已西斜，借衰老之际对照歌与嗟。面对有限性不必只剩哀叹，但不能据此否定真实悲伤。</td></tr><tr><td>九四：突如其來如，焚如，死如，棄如。</td><td>来势突兀而急烈，仿佛迅速燃烧并被弃置。火明过度也能伤物，耀眼不一定可持续。</td></tr><tr><td>六五：出涕沱若，戚嗟若，吉。</td><td>哭泣忧惧却得吉，因为认识到所处责任与危机。眼泪不自动代表软弱，欢乐也不自动代表安全。</td></tr><tr><td>上九：王用出征，有嘉折首，獲匪其醜，无咎。</td><td>记述出征、擒除首恶的古代场景；丑有类、众之义，古注强调不滥及同类，不能按现代美丑理解。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“明兩作離，大人以繼明照于四方。”</p><p><strong>解释</strong>：明相继而起，重在光明的接续。领导、教化或知识的传承不应只依靠一时耀眼的人物，还须让照明持续；这是现代类比，原文仍处于大人治理的语境。</p><p><strong>整体读法与误区</strong>：离卦从初始交错、黄中，到日昃、突焚、忧戚，写出光明并非恒定强光。九三与六五尤其显示情绪不能直接对应吉凶。与<a href="/life/personal/yijing/hexagrams-25-32-part-02#gua-29">坎</a>相对，坎关心险中可信，离关心明所依附；两者都需要具体条件，不是用水火概念给人贴永久性格标签。</p><p><strong>细读线索</strong>：离的两阴分别居二、五，是古注说明柔丽于中、以柔为主的依据；由此可见光明不是一味刚烈。九四突如而焚，与六二黄离的适中构成很强对比；九三日斜与大象继明则把有限生命和接续责任连起来。火需要所附，明也需要承接，在古传中是同一组思想线索。理解这些条件后，才不容易把离只当作耀眼、出名、曝光增加之类单向评价。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9B%A2" target="_blank" rel="noopener noreferrer">《周易·离》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E9%9B%A2" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·离》</a>。</p>',34)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
